// Generated by tools/build-mods.mjs from mods/*/ (mod.json + mod.js). Do not edit: change the mod and rebuild.

// ---- better-coop-items 1.0.0 ----
if (CoopMods.manifest({"id":"better-coop-items","name":"更好的联机道具","version":"1.0.0","author":"黑咖啡和冰月亮","credits":"点子：B 站 蟹堡星人","description":"四个只在双人合作里出现的携带道具：气势纽带、讲究望远镜、粉色香草、共生孢子。","default":"off","api":1})) {
// 更好的联机道具 (better-coop-items) — 点子：B 站 蟹堡星人
// Four held items for two-player co-op. They only come from the 5 选 2 reward screen of a co-op run.
// "队友" below is the other Pokémon on the players' side of the field, whoever owns it.
//
// How each one was read (the original wording is in README.md next to this file):
// - 气势纽带 (MASTER): the holder's teammate, at full HP, takes a move hit that would knock it out -> it stays
//   at 1 HP; the damage beyond that (the hit's damage minus what the teammate lost) goes to the holder as plain
//   damage (it can knock the holder out; the holder's own 气势头带 etc. may still save it). Only move hits
//   count, not weather, poison or recoil. Once per run: afterwards the item stays on the Pokémon, greyed out.
// - 讲究望远镜 (ROGUE): the holder does 1.5x damage to the 集火 target (the enemy both players aim one
//   single-target move at this turn; the same rule as the 集火 banner). Like the 讲究 items it locks the holder
//   into the first move it uses after entering the field (挣扎 when that move runs out of PP); the lock is gone
//   when the holder leaves the field, and starts over when the item is picked up. Staying on the field from
//   one wave to the next keeps the lock, as it keeps stat stages.
// - 粉色香草 (ULTRA): when holder and teammate both have a status condition (中毒, 剧毒, 睡眠, 麻痹, 灼伤, 冰冻),
//   both are cured and the herb is used up. Checked right after a status lands and at the start of every turn
//   (so it also fires when a Pokémon that already has a status joins the other one on the field).
// - 共生孢子 (MASTER): whenever the holder's stat stages really change (up or down, from any source), the
//   teammate gets the same change. A change that came from a spore is never passed on again, so two holders
//   side by side each pass their own changes once and it stops there.
CoopMods.define('better-coop-items', function (api) {
  const B = api.battle;

  // ---- 气势纽带 ----
  const bond = api.item({
    id: 'spirit-bond', name: '气势纽带', tier: 'MASTER', weight: 10, icon: 'linking_cord', // 占位图标：联系绳
    description: '队友满HP时被一击打倒，会留下1点HP，\n多出的伤害由携带者承受。每局只能发动一次。',
  });
  api.on('beforeDamage', ev => {
    const hit = ev.target;
    if (!ev.byMove || !ev.fullHp || !ev.lethal || !B.isPlayer(hit)) return;
    const holder = B.ally(hit);
    if (!holder || !bond.heldBy(holder) || bond.state(holder).used) return;
    const keep = B.hp(hit) - 1, rest = ev.damage - keep;
    bond.state(holder).used = true;
    ev.then(() => {
      B.message(B.name(holder) + '的气势纽带发动了！\n' + B.name(hit) + '撑住了，剩下的伤害由' + B.name(holder) + '承受！');
      if (rest > 0) B.damage(holder, rest);
    });
    api.log('气势纽带: ' + B.name(hit) + ' keeps 1 HP, ' + rest + ' goes to ' + B.name(holder));
    return keep;
  });

  // ---- 讲究望远镜 ----
  const scope = api.item({
    id: 'choice-scope', name: '讲究望远镜', tier: 'ROGUE', weight: 4, icon: 'choice_specs', // 占位图标：讲究眼镜
    description: '对两人集火的目标造成的伤害×1.5。\n上场后只能用第一次使出的招式，下场后重置。',
  });
  // state.since: how many moves the holder had already used on the field when it picked the item up (kept in
  // the save, like the game keeps the move history). A shorter history means it has left the field since.
  function lockOf(p) {
    const st = scope.state(p) || {}, n = B.moveCount(p);
    if (st.since > n) st.since = 0;
    return B.firstMoveSince(p, st.since || 0);
  }
  api.on('give', ev => { if (ev.item === scope.key) scope.state(ev.pokemon).since = B.onField(ev.pokemon) ? B.moveCount(ev.pokemon) : 0; });
  api.on('moveSelect', ev => {
    if (!B.isPlayer(ev.pokemon) || !scope.heldBy(ev.pokemon)) return;
    const lock = lockOf(ev.pokemon);
    if (lock != null && ev.moveId !== lock) return '带着讲究望远镜，只能使用' + B.moveName(ev.pokemon, lock) + '！';
  });
  let told = '';
  api.on('damageCalc', ev => {
    const a = ev.attacker;
    if (!B.isPlayer(a) || B.isPlayer(ev.target) || !scope.heldBy(a)) return;
    if (B.focusTarget() !== B.index(ev.target)) return;
    if (!ev.simulated) {
      const key = B.wave() + ':' + B.turn() + ':' + B.index(a);
      if (told !== key) { told = key; B.message(B.name(a) + '的讲究望远镜对准了集火目标，伤害提升！'); }
    }
    return ev.damage * 1.5;
  });

  // ---- 粉色香草 ----
  const herb = api.item({
    id: 'pink-herb', name: '粉色香草', tier: 'ULTRA', weight: 4, icon: 'power_herb', // 占位图标：强力香草
    description: '携带者和队友同时陷入异常状态时，\n两只一起治愈。使用一次后消失。',
  });
  function checkHerb() {
    for (const p of B.playerField()) {
      if (!herb.heldBy(p)) continue;
      const mate = B.ally(p);
      if (!mate || !B.status(p) || !B.status(mate)) continue;
      herb.remove(p);
      B.message(B.name(p) + '的粉色香草发动了！');
      B.cureStatus(p);
      B.cureStatus(mate);
      api.log('粉色香草: ' + B.name(p) + ' and ' + B.name(mate) + ' cured');
      return;
    }
  }
  api.onPhase('ObtainStatusEffectPhase', checkHerb, 'end');
  api.onPhase('TurnInitPhase', checkHerb, 'start');

  // ---- 共生孢子 ----
  const spore = api.item({
    id: 'symbiosis-spore', name: '共生孢子', tier: 'MASTER', weight: 10, icon: 'max_mushrooms', // 占位图标：极巨菇菇
    description: '携带者的能力升降时，\n队友获得相同的能力升降。',
  });
  api.on('statChange', ev => {
    if (ev.copied || !B.isPlayer(ev.pokemon) || !spore.heldBy(ev.pokemon)) return;
    const mate = B.ally(ev.pokemon);
    if (!mate) return;
    B.message(B.name(ev.pokemon) + '的共生孢子把能力变化传给了' + B.name(mate) + '！');
    B.changeStats(mate, ev.changes);
    api.log('共生孢子: ' + B.name(ev.pokemon) + ' -> ' + B.name(mate) + ' ' + JSON.stringify(ev.changes));
  });
});
}
